function generateApp() {
    delete sap;

    let app = `
        <!DOCTYPE html>
        <html lang="en">
        <head>
            <meta charset="UTF-8">
            <meta name="viewport" content="width=device-width, initial-scale=1.0">
            <meta http-equiv="X-UA-Compatible" content="IE=edge">
            <title>ABAPlorer</title>
            <style>
                html, body, body > div, #container, #container-uiarea {
                    height: 100%;
                }
            </style>
            <script
                id="sap-ui-bootstrap"
                src="https://sapui5.hana.ondemand.com/1.146.0/resources/sap-ui-core.js"
                data-sap-ui-theme="sap_horizon"
                data-sap-ui-resourceroots='{
                    "astrobear.abaplorer": "./"
                }'
                data-sap-ui-oninit="loadAppToContainer"
                data-sap-ui-compatVersion="edge"
                data-sap-ui-async="true"
                data-sap-ui-frameOptions="trusted"
            ></script>
            <style id="abaplorer-custom-css">
/* Repository tree (Main view, left pane) — mirrors the ADT Eclipse look:
   blue object counter and italic gray description next to the node name. */
.abaplorerTreeCounter {
  color: var(--sapInformativeTextColor, #0a6ed1);
}

.abaplorerTreeDesc {
  color: var(--sapContent_LabelColor, #6a6d70);
  font-style: italic;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Repository filter bar (Main view, left pane): inset the search box with
   PADDING, not margin. The SearchField is 100% wide, so horizontal margin would
   push it past its container and clip the right edge (the search icon).
   box-sizing keeps the padding inside the width. */
.abaplorerRepoFilterBar {
  box-sizing: border-box;
  padding: 0.5rem 0.5rem 0.25rem;
}

/* Repository tree density (Main view, left pane) — a smaller font + tighter
   rows bring the file browser closer to the Eclipse ADT project explorer. */
.abaplorerRepoTree .sapMText {
  font-size: 0.8125rem;
}
.abaplorerRepoTree .sapMTreeItemBase {
  min-height: 1.75rem;
}

/* Repository tree horizontal overflow (Main view, left pane).
   The tree sits in a horizontal sap.m.ScrollContainer. By default the list
   fills the viewport and each node's text truncates with an ellipsis. Letting
   the list grow to its widest row (max-content) and rendering node text in full
   makes long object/package names overflow, which the ScrollContainer then
   exposes as a horizontal scrollbar. min-width keeps the rows full-width (so the
   selection highlight still spans the pane) when nothing overflows. */
.abaplorerRepoTree .sapMListUl {
  width: -webkit-max-content;
  width: max-content;
  min-width: 100%;
}
.abaplorerRepoTree .sapMTreeItemBase {
  width: auto;
}
/* Show node name + description in full instead of clipping them, so wide rows
   actually overflow (and thus scroll) rather than ellipsing in place. */
.abaplorerRepoTree .sapMText,
.abaplorerRepoTree .abaplorerTreeDesc {
  overflow: visible;
  text-overflow: clip;
  max-width: none;
}

/* Result comparison heatmap (Compare tab, Result mode).
   Cells are sap.m.ObjectStatus with inverted=true, so the semantic state color
   fills the cell background. Make the status fill the full cell width so the
   heatmap reads as solid bands rather than left-aligned chips. */
.abaplorerHeatmap .sapMObjStatus {
  display: block;
  width: 100%;
  box-sizing: border-box;
  padding: 0 0.5rem;
}

/* Monospace style for XML text areas in detail views */
.fontMonospace textarea {
  font-family: Consolas, Menlo, Monaco, "Courier New", monospace !important;
  font-size: 0.85rem !important;
  line-height: 1.4 !important;
}

/* Bulk Source Edit: a hit's code line, before and after the replacement */
.sapMText.bseCodeLine,
.bseCodeLine .sapMObjStatusText {
  font-family: Consolas, Menlo, Monaco, "Courier New", monospace;
  white-space: pre;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sapMObjStatus.bseCodeLine {
  display: block;
  max-width: 100%;
}


/* Table Compare: the SOURCE marker cell is tinted by side, text stays in the
   normal text colour. Blue / orange is a neutral, colour-blind-safe pair —
   neither side is "wrong", so no red/green. The side comes from the
   data-tc-side attribute the controller writes (see _sourceSide); :has lets
   the tint fill the whole table cell, not just the text span. */
.sapUiTableCell:has(.abaplorerTcSource[data-tc-side="a"]) {
  background-color: var(--sapIndicationColor_5b, #d9ebff);
}

.sapUiTableCell:has(.abaplorerTcSource[data-tc-side="b"]) {
  background-color: var(--sapIndicationColor_3b, #ffdfc3);
}

.abaplorerTcSource.sapMText {
  color: var(--sapTextColor, #1d2d3e);
}

/* BW/4 readiness dashboard: the data bar left of a pivot count. Its width
   is bound per row (a class cannot be), against the largest sibling group.
   The bar is an empty sap.m.HBox; .sapMFlexBox is repeated to outrank the
   transparent background its own style sheet gives it. */
.sapMFlexBox.abaplorerDataBar {
  height: 0.625rem;
  border-radius: 0.125rem;
  background-color: var(--sapInformativeElementColor, #0070f2);
  opacity: 0.45;
}

/* Document Entries: the filter form scrolls on its own once it outgrows a
   third of the screen, so a long filter never pushes the result away. */
.abaplorerDeConditions {
  max-height: 35vh;
}

            </style>
        </head>
        <body class="sapUiBody sapUiSizeCompact" id="content">
            <div
                id="contentContainer"
                data-name="astrobear.abaplorer"
                data-id="container"
                data-settings='{"id" : "astrobear.abaplorer"}'
                data-handle-validation="true"
            ></div>
        </body>
        </html>
    `;

    document.open();
    document.write(app);
    document.close();
}

